INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Klasse in der Objektorientierung immer ein Objekt?', 2, '[{"text": "Nein", "correct": true, "because": "Eine Klasse ist ein Bauplan für Objekte"}, {"text": "Ja", "correct": false, "because": "Objekte werden aus Klassen erstellt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element einer Klasse definiert ihre Eigenschaften?', 3, '[{"text": "Attribute", "correct": true, "because": "Speichern Daten der Klasse"}, {"text": "Methoden", "correct": false, "because": "Definieren Verhalten"}, {"text": "Kommentare", "correct": false, "because": "Nur Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Klasse kann mehrere Objekte erzeugen. b) Jede Klasse muss Methoden enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klassen sind Vorlagen, Methoden optional"}, {"text": "Beides stimmt", "correct": false, "because": "Methoden nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "Objekte sind Instanzen"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schlüsselwort solltest du beim Definieren einer Klasse in Java priorisieren?', 4, '[{"text": "class", "correct": true, "because": "Deklariert eine Klasse"}, {"text": "public", "correct": false, "because": "Zugriffsmodifikator"}, {"text": "void", "correct": false, "because": "Für Methodenrückgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Klasse ohne Attribute definiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Attribute sind optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend nötig"}]');
