INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Klasse in der objektorientierten Programmierung dasselbe wie ein Objekt?', 2, '[{"text": "Nein", "correct": true, "because": "Eine Klasse ist eine Vorlage für Objekte"}, {"text": "Ja", "correct": false, "because": "Objekte sind Instanzen einer Klasse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element einer Klasse definiert ihre Daten?', 3, '[{"text": "Attribute", "correct": true, "because": "Speichern die Eigenschaften der Klasse"}, {"text": "Methoden", "correct": false, "because": "Definieren Verhalten"}, {"text": "Konstruktor", "correct": false, "because": "Initialisiert Objekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Klasse kann mehrere Instanzen haben. b) Eine Klasse muss immer Attribute enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Instanzen sind Objekte, Attribute optional"}, {"text": "Beides stimmt", "correct": false, "because": "Attribute nicht zwingend"}, {"text": "Nur b) stimmt", "correct": false, "because": "Instanzen sind möglich"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schlüsselwort wird in Python verwendet, um eine Klasse zu definieren?', 4, '[{"text": "class", "correct": true, "because": "Deklariert eine neue Klasse"}, {"text": "def", "correct": false, "because": "Für Methoden verwendet"}, {"text": "object", "correct": false, "because": "Basisklasse, nicht Deklaration"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Klasse ohne Methoden definiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Methoden sind optional"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend erforderlich"}]');
